namespace {
using Clock=std::chrono::steady_clock;
uint32_t argument(char**argv,int argc,const char*name,uint32_t fallback){for(int i=1;i+1<argc;++i)if(std::string(argv[i])==name)return uint32_t(std::stoul(argv[i+1]));return fallback;}
double percentile(std::vector<double> values,double p){std::sort(values.begin(),values.end());return values[std::min(values.size()-1,size_t(std::ceil(values.size()*p)-1))];}
std::vector<blah2::channelizer::IlluminatorOutput> convert(std::vector<blah2::wideband_gpu::LaneOutput> input,const std::vector<blah2::channelizer::IlluminatorDefinition>& definitions,const std::vector<uint32_t>& delays){std::vector<blah2::channelizer::IlluminatorOutput> result;result.reserve(input.size());for(size_t i=0;i<input.size();++i){blah2::channelizer::SubbandChannelizer::Output samples;samples.channels=std::move(input[i].channels);samples.firstInputSample=input[i].firstInputSample;samples.hasFirstInputSample=input[i].hasFirstInputSample;samples.inputSamplesPerOutput=input[i].inputSamplesPerOutput;samples.groupDelayInputSamples=delays[i];result.push_back({definitions[i].id,input[i].frequencyHz,std::move(samples)});}return result;}
}

int main(int argc,char**argv)try{
 const uint32_t lanes=argument(argv,argc,"--lanes",2),iterations=argument(argv,argc,"--iterations",20),laneWorkers=argument(argv,argc,"--lane-workers",0);const bool sequential=argument(argv,argc,"--sequential",0)!=0;if((lanes!=2&&lanes!=4&&lanes!=8&&lanes!=12&&lanes!=16)||iterations<2||laneWorkers>lanes)throw std::invalid_argument("--lanes 2|4|8|12|16 --iterations >=2 [--lane-workers N] [--sequential 0|1]");
 const uint32_t inputRate=argument(argv,argc,"--input-rate",60000000),outputRate=argument(argv,argc,"--output-rate",300000),channels=2,samples=inputRate/2,decimation=inputRate/outputRate;if(!outputRate||inputRate%outputRate||outputRate%2)throw std::invalid_argument("input/output rates must form an even-output integer decimation");constexpr uint64_t centerHz=100000000;const uint32_t occupied=outputRate*2/3;
 blah2::wideband_gpu::Config gpuConfig{inputRate,channels,samples,{}};std::vector<blah2::channelizer::IlluminatorDefinition> definitions;std::vector<uint32_t> delays;for(uint32_t lane=0;lane<lanes;++lane){const int64_t offset=(int64_t(lane)-int64_t(lanes/2))*200000;auto taps=blah2::wideband_gpu::designFilter(inputRate,outputRate,occupied,24);delays.push_back(uint32_t((taps.size()-1)/2));definitions.push_back({"lane-"+std::to_string(lane),uint64_t(int64_t(centerHz)+offset),occupied,outputRate,24});gpuConfig.lanes.push_back({definitions.back().frequencyHz,decimation,double(offset),std::move(taps)});}
 std::vector<std::deque<std::complex<double>>> storage(channels);for(auto& channel:storage)channel.resize(samples);std::vector<std::complex<double>> delay(47*decimation);uint32_t random=77123;std::complex<double> turn(1),step=std::polar(1.,2*std::acos(-1.)*42/inputRate);for(uint32_t i=0;i<samples;++i){random=random*1664525u+1013904223u;double re=double(int32_t(random>>16)-32768)/32768.;random=random*1664525u+1013904223u;double im=double(int32_t(random>>16)-32768)/32768.;const std::complex<double> direct(re,im),echo=delay[i%delay.size()]*turn;delay[i%delay.size()]=direct;storage[0][i]=direct;storage[1][i]=direct+.18*echo;turn*=step;if((i&16383u)==16383u)turn/=std::abs(turn);}
 std::vector<const std::deque<std::complex<double>>*> views{&storage[0],&storage[1]};blah2::GpuProcessOptions options;options.executable=GPU_WIDEBAND_WORKER;options.frameMs=5000;auto gpu=blah2::wideband_gpu::createProcess(gpuConfig,"auto",options);
 if(!fftw_init_threads())throw std::runtime_error("FFTW thread initialization failed");
 blah2::set_fftw_planner_threads(1);const size_t activeLaneWorkers=blah2::choose_illuminator_lane_workers(lanes,laneWorkers,blah2::available_cpu_threads());blah2::multi_illuminator::RadarConfig radarConfig;radarConfig.cpiSeconds=.5;radarConfig.delayMin=-10;radarConfig.delayMax=400;radarConfig.dopplerMin=-200;radarConfig.dopplerMax=200;radarConfig.clutterDelayMin=-10;radarConfig.clutterDelayMax=400;radarConfig.minimumDelay=5;radarConfig.workers=1;radarConfig.laneWorkers=activeLaneWorkers;radarConfig.referenceChannel=0;radarConfig.surveillanceChannels.clear();radarConfig.surveillanceChannels.push_back(1);blah2::multi_illuminator::MultiIlluminatorRadar radar(inputRate,channels,definitions,radarConfig);blah2::utility::FixedExecutor submission(1),serialization(std::min<size_t>(lanes,std::max<size_t>(1,blah2::available_cpu_threads()-1)));
 uint64_t first=11;std::vector<blah2::channelizer::IlluminatorOutput> pending;if(!sequential){pending=convert(gpu->processDeques(views,first),definitions,delays);first+=samples;}std::vector<double> total,radarTimes,jsonTimes,staging,worker;uint32_t misses=0,gaps=0;volatile size_t sink=0;
 const auto processRadar=[&](std::vector<blah2::channelizer::IlluminatorOutput> input){std::vector<uint64_t> expectedFirst;for(const auto& lane:input)expectedFirst.push_back(lane.samples.firstInputSample);const auto begin=Clock::now();auto frames=radar.process(std::move(input));const auto radarDone=Clock::now();std::vector<size_t> bytes(frames.size());serialization.parallel_for(frames.size(),[&](size_t i){const auto& frame=frames[i];bytes[i]=frame.map->to_json_km(1700000000000ULL,frame.sampleRateHz).size()+frame.detections->to_json_km(1700000000000ULL,frame.sampleRateHz).size()+frame.tracks->to_json(1700000000000ULL).size();});if(frames.size()!=lanes)throw std::runtime_error("radar lane count changed");for(size_t i=0;i<frames.size();++i){const auto& frame=frames[i];const uint64_t expectedEnd=expectedFirst[i]+uint64_t(outputRate/2-1)*decimation;if(frame.illuminatorId!=definitions[i].id||frame.frequencyHz!=definitions[i].frequencyHz||frame.firstInputSample!=expectedFirst[i]||frame.endInputSample!=expectedEnd||frame.sampleRateHz!=outputRate)throw std::runtime_error("radar metadata differs");}sink^=std::accumulate(bytes.begin(),bytes.end(),size_t(0));return std::pair<double,double>{std::chrono::duration<double,std::milli>(radarDone-begin).count(),std::chrono::duration<double,std::milli>(Clock::now()-radarDone).count()};};
 for(uint32_t frame=0;frame<iterations;++frame){if(frame==iterations/2){first+=317;++gaps;}const auto begin=Clock::now();std::pair<double,double> cpu;if(sequential){pending=convert(gpu->processDeques(views,first),definitions,delays);cpu=processRadar(std::move(pending));}else{auto sent=submission.submit([&]{gpu->beginDeques(views,first);});cpu=processRadar(std::move(pending));sent.get();pending=convert(gpu->finishFrame(),definitions,delays);}const auto timing=gpu->lastTiming();const double elapsed=std::chrono::duration<double,std::milli>(Clock::now()-begin).count();total.push_back(elapsed);radarTimes.push_back(cpu.first);jsonTimes.push_back(cpu.second);staging.push_back(timing.stagingMs);worker.push_back(timing.workerMs);if(elapsed>500)++misses;first+=samples;}
 double drain=0,drainRadar=0;if(!sequential){const auto drainBegin=Clock::now();const auto drainCpu=processRadar(std::move(pending));drain=std::chrono::duration<double,std::milli>(Clock::now()-drainBegin).count();drainRadar=drainCpu.first;}rusage usage{};getrusage(RUSAGE_SELF,&usage);std::cout<<"SUMMARY lanes="<<lanes<<" lane_workers="<<activeLaneWorkers<<" sequential="<<sequential<<" frames="<<iterations<<" p50_ms="<<percentile(total,.5)<<" p95_ms="<<percentile(total,.95)<<" max_ms="<<*std::max_element(total.begin(),total.end())<<" radar_p95_ms="<<percentile(radarTimes,.95)<<" json_p95_ms="<<percentile(jsonTimes,.95)<<" staging_p95_ms="<<percentile(staging,.95)<<" worker_p95_ms="<<percentile(worker,.95)<<" misses="<<misses<<" gaps="<<gaps<<" eof_drain_ms="<<drain<<" eof_radar_ms="<<drainRadar<<" rss_kb="<<usage.ru_maxrss<<" sink="<<sink<<"\n";return 0;
}catch(const std::exception& error){std::cerr<<"FAIL: "<<error.what()<<'\n';return 1;}
